export function createDb() {
  const note = (id, tenantId, text) => [id, { id, tenantId, text, archived: false }];
  return { notes: new Map([note('n1', 't1', 'alpha'), note('n2', 't1', 'beta'), note('n3', 't2', 'gamma')]) };
}

