import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { listNotes, getNote, archiveNotes } from '../src/notes.js';
const ann = { id: 'u1', tenantId: 't1' };
test('lists only the tenant\'s notes', () => {
  expect(listNotes(createDb(), ann).map((n) => n.id).sort()).toEqual(['n1', 'n2']);
});
test('gets a note, throws for a missing one', () => {
  const db = createDb();
  expect(getNote(db, ann, 'n1').text).toBe('alpha');
  expect(() => getNote(db, ann, 'nope')).toThrow();
});
test('archives notes and counts them', () => {
  const db = createDb();
  expect(archiveNotes(db, ann, ['n1', 'n2'])).toBe(2);
  expect(db.notes.get('n1').archived).toBe(true);
  expect(db.notes.get('n3').archived).toBe(false);
});

