import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { getNote, archiveNotes } from '../src/notes.js';
const ann = { id: 'u1', tenantId: 't1' };
const msg = (fn) => { try { fn(); return 'no error'; } catch (e) { return e.message; } };
test('another tenant\'s note cannot be read, and looks like a missing one', () => {
  const db = createDb();
  expect(msg(() => getNote(db, ann, 'n3'))).not.toBe('no error');
  expect(msg(() => getNote(db, ann, 'n3'))).toBe(msg(() => getNote(db, ann, 'does-not-exist')));
});
test('bulk archive never touches another tenant\'s notes', () => {
  const db = createDb();
  try { archiveNotes(db, ann, ['n1', 'n3']); } catch {}
  expect(db.notes.get('n3').archived).toBe(false);
  expect(archiveNotes(db, ann, ['n3'])).toBe(0);
  expect(db.notes.get('n3').archived).toBe(false);
});
